  <div class="bottom-right"><div class="statbox"><strong id="workRate">83%</strong><span>EMPLOYED</span></div><div class="statbox"><strong id="birthRate">+1</strong><span>GROWTH</span></div><div class="statbox"><strong id="danger">LOW</strong><span>THREAT</span></div></div>
 </footer>
 </div>
 <div class="overlay" id="modal"><div class="modal" id="modalContent"></div></div>
+<script>
+(()=>{'use strict';
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),wrap=document.getElementById('worldWrap');
+const ui={credits:240,food:82,scrap:48,power:67,day:1,minute:480,stability:74,happiness:72,pop:12,capacity:16,paused:false,speed:1,selected:null,build:null,zoom:1,cam:{x:27,y:19},hover:null,tick:0,threat:12,expeditions:0,arrival:2};
+const TYPES={shelter:{name:'Hab pod',icon:'⌂',cost:65,scrap:6,capacity:4,color:'#73e5d7'},farm:{name:'Glow farm',icon:'♧',cost:55,scrap:5,color:'#bcf16e'},generator:{name:'Reactor',icon:'ϟ',cost:75,scrap:8,color:'#ffca69'},market:{name:'Night market',icon:'▤',cost:80,scrap:6,color:'#ed78bd'},clinic:{name:'Med bay',icon:'✚',cost:90,scrap:10,color:'#74baff'},watch:{name:'Sentinel',icon:'⌖',cost:110,scrap:12,color:'#ff697f'}};
+const names=['Mira Voss','Jax Rhee','Niko Vale','Aya Sol','Toma Kade','Ren Ilyan','Sera Nyx','Ivo Chen','Luz Ardan','Oren Pike','Vee Okafor','Kiro Tan'];
+const faces=['◉','◈','◉','◍','◎','◈','◍','◉','◎','◍','◈','◎'];
+const roles=['engineer','grower','courier','medic','scrapper','trader','artist','technician'];
+const palette=['#67e2d5','#ff7aa8','#a8d7ff','#f4c46b','#bded72','#d494ee'];
+let buildings=[{type:'shelter',x:25,y:18},{type:'farm',x:28,y:18},{type:'generator',x:25,y:21},{type:'market',x:28,y:21}];
+let citizens=names.map((name,i)=>({id:i,name,face:faces[i],role:roles[i%roles.length],x:24.4+(i%4)*1.25,y:17.2+Math.floor(i/4)*1.15,tx:25,ty:19,needs:{food:65+Math.random()*30,rest:60+Math.random()*35,social:45+Math.random()*50,health:85+Math.random()*15},mood:65+Math.floor(Math.random()*27),state:'working',color:palette[i%palette.length],age:20+Math.floor(Math.random()*35),task:0}));
+let particles=[],events=[{time:'08:00',text:'<b>Haven-09</b> wakes under a violet sky.'},{time:'07:42',text:'<b>Glow farm</b> reports a healthy harvest.'},{time:'07:15',text:'<b>Mira Voss</b> repaired the south conduit.'}];
+const terrain=[];for(let y=0;y<40;y++){terrain[y]=[];for(let x=0;x<56;x++){let v=Math.sin(x*12.98+y*78.23)*43758.5;v-=Math.floor(v);terrain[y][x]=v}}
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function log(text,warn=false){const d=new Date();events.unshift({time:clockText(),text,warn});events=events.slice(0,7);renderEvents()}
+function clockText(){return String(Math.floor(ui.minute/60)%24).padStart(2,'0')+':'+String(ui.minute%60).padStart(2,'0')}
+function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1900)}
+function resize(){const r=wrap.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';ctx.setTransform(d,0,0,d,0,0)}
+new ResizeObserver(resize).observe(wrap);resize();
+function screenToWorld(px,py){const w=wrap.clientWidth,h=wrap.clientHeight,z=32*ui.zoom;return{x:(px-w/2)/z+ui.cam.x,y:(py-h/2)/z+ui.cam.y}}
+function worldToScreen(x,y){const w=wrap.clientWidth,h=wrap.clientHeight,z=32*ui.zoom;return{x:(x-ui.cam.x)*z+w/2,y:(y-ui.cam.y)*z+h/2}}
+function addParticle(x,y,color){for(let i=0;i<7;i++)particles.push({x,y,vx:rand(-.045,.045),vy:rand(-.1,.015),life:rand(.35,.8),max:.8,color})}
+function render(){const w=wrap.clientWidth,h=wrap.clientHeight,z=32*ui.zoom;ctx.clearRect(0,0,w,h);ctx.fillStyle='#0b1519';ctx.fillRect(0,0,w,h);
+ const x0=Math.max(0,Math.floor(ui.cam.x-w/(2*z))-2),x1=Math.min(56,Math.ceil(ui.cam.x+w/(2*z))+2),y0=Math.max(0,Math.floor(ui.cam.y-h/(2*z))-2),y1=Math.min(40,Math.ceil(ui.cam.y+h/(2*z))+2);
+ for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let p=worldToScreen(x+.5,y+.5),n=terrain[y][x];ctx.fillStyle=n>.90?'#122126':n<.08?'#0c191e':((x+y)%2?'#0d191e':'#0e1a1f');ctx.fillRect(Math.floor(p.x-z/2),Math.floor(p.y-z/2),Math.ceil(z),Math.ceil(z));if(n>.974){ctx.fillStyle='#24434a';ctx.fillRect(p.x-z*.14,p.y-z*.1,Math.max(1,z*.1),Math.max(1,z*.1))}if(n<.025){ctx.strokeStyle='#192e33';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-z*.25,p.y);ctx.lineTo(p.x+z*.25,p.y-z*.1);ctx.stroke()}}
+ // abandoned infrastructure and glowing road grid
+ for(let x=8;x<49;x+=8){let a=worldToScreen(x,7),b=worldToScreen(x,33);ctx.strokeStyle='#183036';ctx.lineWidth=1;ctx.setLineDash([3,8]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.setLineDash([])}
+ // district perimeter
+ const c=worldToScreen(27,20);ctx.strokeStyle='#58ded51c';ctx.lineWidth=1;ctx.setLineDash([4,6]);ctx.strokeRect(c.x-7*z,c.y-5*z,14*z,10*z);ctx.setLineDash([]);
+ buildings.forEach(b=>drawBuilding(b,z));
+ citizens.forEach(cit=>drawCitizen(cit,z));
+ for(let i=particles.length-1;i>=0;i--){let p=particles[i],s=worldToScreen(p.x,p.y);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(s.x,s.y,2.2,2.2);ctx.globalAlpha=1;p.x+=p.vx;p.y+=p.vy;p.life-=.016;if(p.life<=0)particles.splice(i,1)}
+ if(ui.build&&ui.hover){const p=worldToScreen(Math.floor(ui.hover.x)+.5,Math.floor(ui.hover.y)+.5);ctx.strokeStyle='#5de7dc';ctx.globalAlpha=.75;ctx.strokeRect(p.x-z/2,p.y-z/2,z,z);ctx.globalAlpha=1}
+ // subtle scanlines
+ ctx.fillStyle='#c0efff08';for(let y=0;y<h;y+=4)ctx.fillRect(0,y,w,1);
+ requestAnimationFrame(render)}
+function drawBuilding(b,z){const p=worldToScreen(b.x+.5,b.y+.5),s=z*.72,t=TYPES[b.type];ctx.save();ctx.translate(Math.round(p.x),Math.round(p.y));ctx.shadowBlur=12;ctx.shadowColor=t.color+'55';
+ ctx.fillStyle='#0a1116';ctx.fillRect(-s*.5,-s*.43,s,s*.8);ctx.shadowBlur=0;ctx.strokeStyle=t.color;ctx.lineWidth=Math.max(1,z*.045);ctx.strokeRect(-s*.45,-s*.4,s*.9,s*.76);ctx.fillStyle='#17282c';ctx.fillRect(-s*.36,-s*.3,s*.72,s*.55);
+ // roof / structure marks
+ ctx.fillStyle=t.color;ctx.globalAlpha=.75;ctx.fillRect(-s*.28,-s*.23,s*.56,s*.07);ctx.globalAlpha=.45;ctx.fillRect(-s*.28,s*.01,s*.17,s*.18);ctx.fillRect(s*.1,s*.01,s*.17,s*.18);ctx.globalAlpha=1;
+ ctx.font=`${Math.max(10,s*.43)}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=t.color;ctx.fillText(t.icon,0,-s*.03);
+ ctx.fillStyle='#121f23';ctx.fillRect(-s*.5,s*.4,s,s*.2);ctx.fillStyle=t.color;ctx.fillRect(-s*.42,s*.45,s*.84,s*.035);ctx.restore()}
+function drawCitizen(c,z){const p=worldToScreen(c.x,c.y),s=Math.max(7,z*.25);ctx.fillStyle='#0009';ctx.fillRect(p.x-s*.48,p.y+s*.33,s*.96,s*.17);ctx.fillStyle=c.color;ctx.fillRect(Math.round(p.x-s*.35),Math.round(p.y-s*.14),s*.7,s*.52);ctx.fillStyle='#d5e8e4';ctx.fillRect(Math.round(p.x-s*.28),Math.round(p.y-s*.48),s*.56,s*.39);ctx.fillStyle='#17252a';ctx.fillRect(p.x-s*.19,p.y-s*.33,s*.1,s*.08);ctx.fillRect(p.x+s*.08,p.y-s*.33,s*.1,s*.08);ctx.fillStyle=c.color;ctx.fillRect(p.x-s*.25,p.y+s*.38,s*.18,s*.13);ctx.fillRect(p.x+s*.07,p.y+s*.38,s*.18,s*.13);if(ui.selected===c.id){ctx.strokeStyle='#e6ff99';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(p.x,p.y,s*.68,s*.76,0,0,Math.PI*2);ctx.stroke()}}
+requestAnimationFrame(render);

