requestAnimationFrame(render);
function renderEvents(){const el=document.getElementById('events');el.innerHTML=events.slice(0,5).map(e=>`<div class="event ${e.warn?'warn':''}"><time>${e.time}</time><div>${e.text}</div></div>`).join('')}
function renderResidents(){const list=document.getElementById('residentList'),roster=document.getElementById('roster');list.innerHTML=citizens.slice(0,4).map(c=>`<div class="citizen" data-cit="${c.id}"><div class="portrait" style="color:${c.color}">${c.face}</div><div class="cit-info"><div class="cit-name">${c.name}</div><div class="cit-job">${c.state.toUpperCase()} · ${c.role}</div></div><div class="mood">${Math.round(c.mood)}%</div></div>`).join('');roster.innerHTML=citizens.slice(0,8).map(c=>`<div class="people-card ${ui.selected===c.id?'selected':''}" data-cit="${c.id}"><span class="mini-face" style="color:${c.color}">${c.face}</span><div><div class="mini-name">${c.name.split(' ')[0]}</div><div class="mini-work">${c.role.toUpperCase()}</div></div></div>`).join('');document.querySelectorAll('[data-cit]').forEach(el=>el.onclick=()=>selectCitizen(+el.dataset.cit))}
function selectCitizen(id){ui.selected=id;let c=citizens.find(a=>a.id===id);if(!c)return;document.getElementById('modeLabel').textContent='CITIZEN FOCUS';ui.cam.x=c.x;ui.cam.y=c.y;renderResidents();renderInspector(c)}
function renderInspector(c){const panel=document.querySelector('.right');panel.innerHTML=`<div class="eyebrow">RESIDENT PROFILE</div><div class="right-title">${c.name}</div><div class="right-sub">${c.role.toUpperCase()} · AGE ${c.age} · HAVEN-09</div><div class="inspector"><div class="inspect-head"><div class="portrait" style="color:${c.color}">${c.face}</div><div><div class="inspect-name">${c.name}</div><div class="inspect-role">${c.state.toUpperCase()} · ${c.mood>70?'CONTENT':c.mood>40?'STEADY':'RESTLESS'}</div></div></div>${Object.entries({NOURISHMENT:c.needs.food,REST:c.needs.rest,SOCIAL:c.needs.social,HEALTH:c.needs.health}).map(([n,v])=>`<div class="need"><div class="needline"><span>${n}</span><span>${Math.round(v)}%</span></div><div class="needbar"><i style="width:${v}%;background:${v<35?'var(--pink)':'var(--lime)'}"></i></div></div>`).join('')}<button class="action-btn" id="encourage">✦ ENCOURAGE THIS RESIDENT · 12 ◈</button></div><div class="right-section"><h3>PERSONAL NOTE</h3><div class="event"><time>NOW</time><div><b>${c.name.split(' ')[0]}</b> is ${c.state} in the district. Their daily routine is self-directed.</div></div><div class="event"><time>LINK</time><div>Social circle: <b>${citizens.filter(a=>a.id!==c.id).slice(0,3).map(a=>a.name.split(' ')[0]).join(', ')}</b></div></div></div><button class="action-btn" id="backOverview">← BACK TO DISTRICT</button>`;document.getElementById('encourage').onclick=()=>{if(ui.credits<12){toast('Not enough credits');return}ui.credits-=12;c.mood=clamp(c.mood+14,0,100);c.needs.social=clamp(c.needs.social+20,0,100);toast(`${c.name.split(' ')[0]} feels seen.`);renderInspector(c);updateUI()};document.getElementById('backOverview').onclick=()=>{ui.selected=null;document.getElementById('modeLabel').textContent='OBSERVER';restoreOverview()}}
function restoreOverview(){const aside=document.querySelector('.right');aside.innerHTML=`<div class="eyebrow">LIVE FEED <span style="color:var(--cyan)">●</span></div><div class="right-title">The settlement</div><div class="right-sub">AUTONOMOUS CIVILIZATION · REAL TIME</div><div class="overview-card"><div class="ovrow"><span>POPULATION</span><b id="popVal">${citizens.length} / ${ui.capacity}</b></div><div class="ovrow"><span>EMPLOYMENT</span><b id="employment">${employment()}%</b></div><div class="ovrow"><span>HAPPINESS</span><b id="happyVal" class="trend">${Math.round(averageMood())}%</b></div><div class="ovrow"><span>DAILY TRADE</span><b id="tradeVal">+${tradeIncome()} ◈</b></div></div><div class="right-section"><h3>RESIDENTS <span id="residentCount">${citizens.length}</span></h3><div id="residentList"></div></div><div class="right-section"><h3>DISTRICT PULSE</h3><div id="events"></div></div>`;renderResidents();renderEvents()}
function employment(){return Math.round(citizens.filter(c=>c.role!=='artist').length/Math.max(1,citizens.length)*100)}function averageMood(){return citizens.reduce((s,c)=>s+c.mood,0)/Math.max(1,citizens.length)}function tradeIncome(){return 10+buildings.filter(b=>b.type==='market').length*8}
function updateUI(){document.getElementById('credits').textContent=Math.floor(ui.credits);document.getElementById('food').textContent=Math.floor(ui.food);document.getElementById('scrap').textContent=Math.floor(ui.scrap);document.getElementById('power').textContent=Math.floor(ui.power);document.getElementById('clock').textContent=`DAY ${String(ui.day).padStart(2,'0')} · ${clockText()}`;document.getElementById('cycle').textContent=String(ui.day).padStart(2,'0');document.getElementById('popVal')&&(document.getElementById('popVal').textContent=`${citizens.length} / ${ui.capacity}`);document.getElementById('employment')&&(document.getElementById('employment').textContent=employment()+'%');document.getElementById('happyVal')&&(document.getElementById('happyVal').textContent=Math.round(averageMood())+'%');document.getElementById('tradeVal')&&(document.getElementById('tradeVal').textContent='+'+tradeIncome()+' ◈');document.getElementById('residentCount')&&(document.getElementById('residentCount').textContent=citizens.length);document.getElementById('populationCount').innerHTML=`${citizens.length} <span>RESIDENTS</span>`;document.getElementById('arrival').textContent=ui.arrival<=0?'eligible now':`in ${ui.arrival} cycle${ui.arrival===1?'':'s'}`;document.getElementById('workRate').textContent=employment()+'%';document.getElementById('birthRate').textContent='+'+(ui.arrival<=0&&citizens.length<ui.capacity?1:0);document.getElementById('danger').textContent=ui.threat>60?'HIGH':ui.threat>30?'ELEVATED':'LOW';document.getElementById('stabilityText').textContent=Math.round(ui.stability)+'%';document.getElementById('stabilityBar').style.width=ui.stability+'%';let habit=clamp(50+buildings.filter(b=>b.type==='shelter').length*8+buildings.filter(b=>b.type==='clinic').length*5,0,100);document.getElementById('habitText').textContent=habit+'%';document.getElementById('habitBar').style.width=habit+'%';if(!ui.selected)renderResidents()}
function pickTask(c){let options=[{x:28,y:18,state:'tending the glow farm'},{x:25,y:21,state:'checking the reactor'},{x:28,y:21,state:'trading at the night market'},{x:25,y:18,state:'resting in the hab pod'},{x:21,y:19,state:'scavenging the perimeter'},{x:30,y:23,state:'meeting a neighbor'}];let a=options[Math.floor(Math.random()*options.length)];c.tx=a.x+rand(-.5,.5);c.ty=a.y+rand(-.5,.5);c.state=a.state.split(' ').slice(-2).join(' ');c.task=rand(7,18)}
function dayCycle(){ui.day++;ui.minute=0;let farms=buildings.filter(b=>b.type==='farm').length,gens=buildings.filter(b=>b.type==='generator').length,markets=buildings.filter(b=>b.type==='market').length,clinics=buildings.filter(b=>b.type==='clinic').length;
 ui.food=clamp(ui.food+farms*24-citizens.length*1.35,0,999);ui.power=clamp(ui.power+gens*20-citizens.length*.7-buildings.length*.5,0,999);ui.credits+=10+markets*18+Math.max(0,Math.floor(citizens.length/3));ui.scrap+=Math.floor(rand(2,7));ui.happiness=clamp(averageMood(),0,100);ui.stability=clamp(ui.stability+(ui.food>5?2:-8)+(ui.power>5?1:-4)+(ui.happiness>55?1:-2),0,100);ui.threat=clamp(ui.threat+rand(-10,14)-buildings.filter(b=>b.type==='watch').length*11,0,100);citizens.forEach(c=>{c.needs.food=clamp(c.needs.food+45,0,100);c.needs.rest=clamp(c.needs.rest+40,0,100);c.mood=clamp(c.mood+(ui.food>0?2:-11)+(ui.power>0?1:-5)+(Math.random()*8-4),5,100);if(clinics)c.needs.health=clamp(c.needs.health+clinics*8,0,100)});
 if(ui.threat>55){const watch=buildings.filter(b=>b.type==='watch').length;if(watch){ui.threat=clamp(ui.threat-28,0,100);ui.scrap=Math.max(0,ui.scrap-3);log('<b>Sentinel</b> repelled scavengers at the outer fence.',true);for(let i=0;i<18;i++)addParticle(30,18,'#ff697f')}else{ui.credits=Math.max(0,ui.credits-30);ui.food=Math.max(0,ui.food-8);ui.stability=clamp(ui.stability-9,0,100);ui.threat=28;log('<b>Raiders</b> hit an unguarded supply cache.',true)}}else log(`<b>Cycle ${String(ui.day).padStart(2,'0')}</b> closes. The district tallies its work.`);
 ui.arrival--;if(ui.arrival<=0&&citizens.length<ui.capacity){const i=citizens.length;const newcomer={id:Date.now(),name:['Sol','Kestrel','Eli','Rin','Nova','Pax'][Math.floor(Math.random()*6)]+' '+['Morrow','Quill','Sato','Grey','Dae'][Math.floor(Math.random()*5)],face:faces[i%faces.length],role:roles[i%roles.length],x:20+rand(0,3),y:24+rand(0,2),tx:26,ty:20,needs:{food:80,rest:75,social:65,health:90},mood:76,state:'arriving',color:palette[i%palette.length],age:rand(18,45)|0,task:5};citizens.push(newcomer);ui.arrival=2;log(`<b>${newcomer.name}</b> arrived seeking a safer life.`)}else if(citizens.length>=ui.capacity)ui.arrival=1;
 if(citizens.length>=30&&ui.day>=10){showWin()}updateUI();if(!ui.selected)restoreOverview()}
setInterval(()=>{if(ui.paused)return;ui.tick++;ui.minute+=8*ui.speed;if(ui.minute>=1440){dayCycle()}citizens.forEach(c=>{c.needs.food=clamp(c.needs.food-.22*ui.speed,0,100);c.needs.rest=clamp(c.needs.rest-.13*ui.speed,0,100);c.needs.social=clamp(c.needs.social-.10*ui.speed,0,100);c.task-=ui.speed;if(c.task<=0||Math.hypot(c.x-c.tx,c.y-c.ty)<.3)pickTask(c);let dx=c.tx-c.x,dy=c.ty-c.y,d=Math.hypot(dx,dy)||1,step=.027*ui.speed;c.x+=dx/d*Math.min(step,d);c.y+=dy/d*Math.min(step,d);if(Math.random()<.018)c.mood=clamp(c.mood+rand(-2,3),0,100)});if(ui.tick%3===0)updateUI();if(ui.tick%14===0&&Math.random()<.6){const c=citizens[Math.floor(Math.random()*citizens.length)];log(`<b>${c.name.split(' ')[0]}</b> ${['shared a meal with a neighbor','found a pre-collapse keepsake','swapped shifts at the market','told stories by the reactor'][Math.floor(Math.random()*4)]}.`)}},1000);

