if(citizens.length>=30&&ui.day>=10){showWin()}if(ui.stability<=0){showLose()}updateUI();if(!ui.selected)restoreOverview()}
function showModal(title,body,content,button='CONTINUE'){const ov=document.getElementById('modal'),box=document.getElementById('modalContent');box.innerHTML=`<div class="eyebrow">AFTERLIGHT · FIELD DISPATCH</div><h2>${title}</h2><p>${body}</p>${content}<button class="primary" id="modalAction">${button}</button>`;ov.classList.add('open');return document.getElementById('modalAction')}
function showIntro(){ui.paused=true;document.getElementById('pauseBtn').textContent='▶';let b=showModal('A city at the edge of night.','The old world went quiet. Twelve strangers kept the lights on. Now Haven-09 is yours to guide — while its people make their own lives.',`<div class="modal-grid"><div class="mission"><b>BUILD TO THRIVE</b><small>Place farms, shelters and power to grow a self-sustaining district. Buildings need credits and scrap.</small></div><div class="mission"><b>LET LIFE HAPPEN</b><small>Residents work, rest, socialize and form their own routines in real time. Click anyone to check in.</small></div><div class="mission"><b>WATCH THE FRONTIER</b><small>Scavenger raids grow bolder. Sentinel towers defend supplies. Expeditions bring back rare salvage.</small></div><div class="mission"><b>SECURE THE FUTURE</b><small>Reach 30 residents and keep the district stable through 10 cycles. This is your new beginning.</small></div></div>`,'ENTER HAVEN-09');b.onclick=()=>{document.getElementById('modal').classList.remove('open');ui.paused=false;document.getElementById('pauseBtn').textContent='Ⅱ';log('<b>Warden</b> took command. The first cycle begins.');updateUI()}}
function showWin(){if(document.getElementById('modal').classList.contains('open'))return;ui.paused=true;const b=showModal('The lights hold.','Haven-09 is no longer a refuge — it is a home. Thirty lives, a thriving trade network, and a future built from the ruins.',`<div class="modal-grid"><div class="mission"><b>${ui.day} CYCLES</b><small>Survived on the edge.</small></div><div class="mission"><b>${citizens.length} RESIDENTS</b><small>A community became a civilization.</small></div></div>`,'KEEP PLAYING');b.onclick=()=>{document.getElementById('modal').classList.remove('open');ui.paused=false}}
function showLose(){if(document.getElementById('modal').classList.contains('open'))return;ui.paused=true;const b=showModal('The signal fades.','Stability reached zero. Haven-09 needs food, power and people who still believe tomorrow is possible.',`<div class="mission"><b>LASTED ${ui.day} CYCLES</b><small>Every city is a second chance.</small></div>`,'RESTART DISTRICT');b.onclick=()=>location.reload()}
function openExpedition(){if(ui.paused&&document.getElementById('modal').classList.contains('open'))return;const b=showModal('Send a crew beyond the wall.','Choose a route. Expeditions take 18 seconds of real time. The crew may return with scrap, credits and stories — but the old city is never safe.',`<div class="modal-grid"><div class="mission"><b>✧ FLOODLIGHT ARCADE</b><small>Cost: 25 ◈ · Low risk<br>Recover consumer tech and trade goods.</small><button class="action-btn" data-route="arcade">DEPLOY CREW</button></div><div class="mission"><b>☣ GLASS QUARTER</b><small>Cost: 10 ◈ · High risk<br>Search for rare reactor components.</small><button class="action-btn" data-route="glass">DEPLOY CREW</button></div></div><div id="missionMsg" style="font:9px var(--mono);color:var(--amber);min-height:14px"></div>`,'CLOSE');b.onclick=()=>document.getElementById('modal').classList.remove('open');document.querySelectorAll('[data-route]').forEach(btn=>btn.onclick=e=>{e.stopPropagation();let route=btn.dataset.route,cost=route==='arcade'?25:10;if(ui.credits<cost){document.getElementById('missionMsg').textContent='Not enough credits to send a crew.';return}if(!citizens.length){document.getElementById('missionMsg').textContent='No crew available.';return}ui.credits-=cost;ui.expeditions++;btn.disabled=true;btn.textContent='CREW IN THE FIELD…';document.getElementById('missionMsg').textContent='Crew departed. Check back in 18 seconds.';updateUI();setTimeout(()=>{let success=Math.random()>(route==='arcade'?.16:.38);if(success){let salvage=route==='arcade'?Math.floor(rand(12,26)):Math.floor(rand(22,42));ui.scrap+=salvage;ui.credits+=Math.floor(rand(8,24));ui.stability=clamp(ui.stability+2,0,100);log(`<b>Expedition returned</b> with ${salvage} scrap and a story to tell.`);toast(`Expedition returned · +${salvage} scrap`)}else{ui.threat=clamp(ui.threat+15,0,100);ui.stability=clamp(ui.stability-5,0,100);log('<b>Expedition lost contact</b> in the Glass Quarter.',true);toast('Crew overdue · signal lost')}updateUI();if(!ui.paused)document.getElementById('modal').classList.remove('open');else document.getElementById('missionMsg').textContent=success?'Crew returned safely. Salvage added to stores.':'Signal lost. The crew never checked in.'},18000)})}
function placeBuilding(x,y){const type=ui.build,t=TYPES[type];if(!t)return;if(ui.credits<t.cost||ui.scrap<t.scrap){toast(`Need ${t.cost} credits and ${t.scrap} scrap`);return}if(x<1||y<1||x>54||y>38||buildings.some(b=>Math.hypot(b.x-x,b.y-y)<1.55)){toast('No room there — choose an open tile');return}ui.credits-=t.cost;ui.scrap-=t.scrap;buildings.push({type,x,y});if(type==='shelter')ui.capacity+=4;ui.build=null;document.querySelectorAll('.build-item').forEach(b=>b.classList.remove('active'));document.getElementById('modeLabel').textContent='OBSERVER';for(let i=0;i<15;i++)addParticle(x+.5,y+.5,t.color);log(`<b>${t.name}</b> commissioned on the district edge.`);toast(`${t.name} constructed`);updateUI()}
document.querySelectorAll('.build-item').forEach(btn=>btn.onclick=()=>{const type=btn.dataset.build;if(ui.build===type){ui.build=null;btn.classList.remove('active');document.getElementById('modeLabel').textContent='OBSERVER';return}ui.build=type;document.querySelectorAll('.build-item').forEach(b=>b.classList.toggle('active',b===btn));document.getElementById('modeLabel').textContent='PLACE '+TYPES[type].name.toUpperCase();toast(`Select an open tile to place ${TYPES[type].name}`)});
document.getElementById('cancelBuild').onclick=()=>{ui.build=null;document.querySelectorAll('.build-item').forEach(b=>b.classList.remove('active'));document.getElementById('modeLabel').textContent='OBSERVER'};
document.getElementById('expeditionBtn').onclick=openExpedition;
document.getElementById('pauseBtn').onclick=()=>{ui.paused=!ui.paused;document.getElementById('pauseBtn').textContent=ui.paused?'▶':'Ⅱ';toast(ui.paused?'Simulation paused':'Simulation resumed')};
document.getElementById('speedBtn').onclick=()=>{ui.speed=ui.speed===1?2:ui.speed===2?3:1;document.getElementById('speedBtn').textContent='×'+ui.speed;toast(`Simulation speed ×${ui.speed}`)};
document.getElementById('zoomIn').onclick=()=>ui.zoom=clamp(ui.zoom*1.2,.65,1.8);document.getElementById('zoomOut').onclick=()=>ui.zoom=clamp(ui.zoom/1.2,.65,1.8);document.getElementById('centerBtn').onclick=()=>{ui.cam.x=27;ui.cam.y=20;ui.selected=null;document.getElementById('modeLabel').textContent='OBSERVER';restoreOverview()};
let down=null;canvas.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),p=screenToWorld(e.clientX-r.left,e.clientY-r.top);ui.hover=p;document.getElementById('coords').textContent=`X ${String(Math.floor(p.x)).padStart(3,'0')} · Y ${String(Math.floor(p.y)).padStart(3,'0')}`;if(down&&e.buttons===1&&(Math.abs(e.clientX-down.x)>4||Math.abs(e.clientY-down.y)>4)){down.moved=true;ui.cam.x-=(e.clientX-down.x)/(32*ui.zoom);ui.cam.y-=(e.clientY-down.y)/(32*ui.zoom);down.x=e.clientX;down.y=e.clientY}});canvas.addEventListener('pointerup',e=>{if(!down)return;const wasMoved=down.moved;down=null;if(wasMoved)return;const r=canvas.getBoundingClientRect(),p=screenToWorld(e.clientX-r.left,e.clientY-r.top);if(ui.build){placeBuilding(Math.floor(p.x),Math.floor(p.y));return}let c=citizens.find(a=>Math.hypot(a.x-p.x,a.y-p.y)<.48);if(c)selectCitizen(c.id);else{ui.selected=null;document.getElementById('modeLabel').textContent='OBSERVER';restoreOverview()}});
canvas.addEventListener('wheel',e=>{e.preventDefault();ui.zoom=clamp(ui.zoom*(e.deltaY<0?1.1:.91),.65,1.8)},{passive:false});window.addEventListener('keydown',e=>{if(e.key==='Escape'){ui.build=null;document.querySelectorAll('.build-item').forEach(b=>b.classList.remove('active'));document.getElementById('modeLabel').textContent='OBSERVER';document.getElementById('modal').classList.remove('open')}if(e.key===' '){e.preventDefault();document.getElementById('pauseBtn').click()}if(e.key==='+'||e.key==='=')ui.zoom=clamp(ui.zoom*1.2,.65,1.8);if(e.key==='-')ui.zoom=clamp(ui.zoom/1.2,.65,1.8)});
renderEvents();renderResidents();restoreOverview();updateUI();showIntro();
})();
</script>
</body>
</html>

